21: function initMap(){map=[];let terrainSeed=43812;const mapRand=()=>{terrainSeed=(terrainSeed*1664525+1013904223)>>>0;return terrainSeed/4294967296};for(let y=0;y<H;y++)for(let x=0;x<W;x++){let v=Math.sin(x*.31)*Math.cos(y*.25)+Math.sin((x+y)*.12),type='grass';if(x<4+(Math.sin(y*.35)*2|0)||x>W-5)type='water';else if(v>1.12)type='hill';else if(v>.56&&mapRand()<.48)type='forest';map.push({x,y,type,building:null});}}
