30: function stats(){let data=[['Population',fmt(s.pop)],['Treasury',money(s.cash)],['Happiness',Math.round(s.happiness)+'%'],['Crime',Math.round(s.crime)+'%'],['Pollution',Math.round(s.pollution)],['Milestone',rank()],['Developed lots',s.buildings.filter(b=>b.level>1).length],['City land',s.buildings.length+' lots'],['Day',s.day]];document.getElementById('statsGrid').innerHTML=data.map(([a,b])=>`<div class="statbox"><label>${a}</label><b>${b}</b></div>`).join('');document.getElementById('journal').innerHTML=`Current milestone: <b style="color:var(--lime)">${rank()}</b><br>Next unlock: ${s.pop<1800?'Town at 1,800 residents':s.pop<6000?'City at 6,000 residents':s.pop<20000?'Metropolis at 20,000 residents':'All milestones reached'}<br>Residents are happiest with road access, utilities, parks, and city services.`}
31: function calc(){let b=s.buildings,res=b.filter(x=>['res','resmid','reshigh'].includes(x.type)),com=b.filter(x=>['shop','office','mall'].includes(x.type)),ind=b.filter(x=>['farm','factory','tech'].includes(x.type));let power=b.reduce((n,x)=>n+({wind:100,solar:160,coal:340,nuclear:900}[x.type]||0),0),water=b.reduce((n,x)=>n+({pump:180,tower:220,treatment:380}[x.type]||0),0),pUse=Math.min(100,Math.round(power?((s.pop*.08)/power*100):0)),wUse=Math.min(100,Math.round(water?((s.pop*.07)/water*100):0)),parks=b.filter(x=>x.type==='park').length,police=b.filter(x=>x.type==='police').length,health=b.filter(x=>x.type==='hospital').length,schools=b.filter(x=>['school','university'].includes(x.type)).length;s.pollution=Math.max(0,8+ind.length*4+b.filter(x=>x.type==='coal').length*18-(s.policies.green?18:0));s.crime=Math.max(0,Math.min(95,18-police*12+s.pop/3000-(s.funds.police-100)*.08));s.happiness=Math.max(5,Math.min(99,66+parks*3+health*2+schools*1.3+(s.policies.transit?8:0)+(s.policies.green?5:0)+(s.policies.festival?10:0)-s.pollution*.45-s.crime*.25-(pUse>90?12:0)-(wUse>90?12:0)-(s.taxes.res-8)*1.3-(s.policies.night?3:0)));let income=(s.pop*s.taxes.res*.004+com.length*s.taxes.com*2.5+ind.length*s.taxes.ind*2.5)*(1+(s.policies.subsidies?.25:0))*(s.policies.night?1.18:1),expense=b.reduce((n,x)=>n+(x.upkeep??items.find(i=>i.id===x.type)?.upkeep??0),0)+Object.values(s.funds).reduce((n,v)=>n+v*.008,0)+policies.reduce((n,p)=>n+(s.policies[p.id]?p.upkeep:0),0);return{res,com,ind,power,water,pUse,wUse,income:income-expense,parks}}
